import random
import chess
import test_random as T

def has_ep_capture(board):
    for m in board.legal_moves:
        if board.is_en_passant(m):
            return True
    return False

def has_promo(board):
    for m in board.legal_moves:
        if m.promotion:
            return True
    return False

def has_castle(board):
    for m in board.legal_moves:
        if board.is_castling(m):
            return True
    return False

def main():
    rnd = random.Random(12345)
    tested = 0
    tested_kinds = {}
    max_test = 250
    games = 0
    while tested < max_test and games < 500:
        games += 1
        board = chess.Board()
        for ply in range(160):
            if board.is_game_over():
                break
            if board.turn == chess.WHITE:
                kinds = []
                if board.is_check(): kinds.append("check")
                if board.ep_square is not None: kinds.append("ep_avail")
                if has_ep_capture(board): kinds.append("ep_legal")
                if has_promo(board): kinds.append("promo")
                if has_castle(board): kinds.append("castle_legal")
                if board.has_castling_rights(chess.WHITE): kinds.append("castle_rights")
                if board.has_castling_rights(chess.BLACK): kinds.append("black_rights")
                if ply % 17 == 0: kinds.append("sample")
                if kinds and tested < max_test:
                    if not T.check_pos(board.fen()):
                        print("FAILED", board.fen(), kinds)
                        return False
                    tested += 1
                    for k in kinds:
                        tested_kinds[k] = tested_kinds.get(k, 0) + 1
            moves = list(board.legal_moves)
            if not moves:
                break
            board.push(rnd.choice(moves))
    print("tested", tested, "games", games, tested_kinds)
    return True

if __name__ == "__main__":
    ok = main()
    print("OK" if ok else "FAILED")

